using System;using System.IO;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Collections;using SOFCMeas;
class OnceSmoke{
static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
static void Pump(Task t){while(!t.IsCompleted){Application.DoEvents();Thread.Sleep(2);}t.GetAwaiter().GetResult();}
[STAThread]static void Main(){Application.EnableVisualStyles();var root=Path.Combine(Path.GetTempPath(),"SimOnce-"+Guid.NewGuid());Environment.SetEnvironmentVariable("SOFCMEAS_ROOT",root);Directory.CreateDirectory(Path.Combine(root,"conf"));File.WriteAllText(Path.Combine(root,"conf","SOFCMeas.config"),"<configuration><appSettings/></configuration>");
var type=typeof(StationView);var storage=Activator.CreateInstance(type.Assembly.GetType("SOFCMeas.InspectionStorageService"),true);
using(var host=new Form())using(var v=new StationView()){host.Controls.Add(v);host.StartPosition=FormStartPosition.Manual;host.Location=new System.Drawing.Point(-32000,-32000);host.Show();var h=v.Handle;SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());type.GetMethod("BindHistory",F).Invoke(v,new[]{storage,(object)"#1"});var run=(Task)type.GetMethod("RunSimulationAsync",F).Invoke(v,new object[]{1});Pump(run);for(int i=0;i<100;i++){Application.DoEvents();Thread.Sleep(2);}if((int)type.GetField("m_InspectionCount",F).GetValue(v)!=1)throw new Exception("Inspection count");if(!(bool)type.GetProperty("CollectionEnabled",F).GetValue(v,null))throw new Exception("START lost");if(type.GetField("m_ReviewChart",F).GetValue(v)!=null)throw new Exception("Unexpected automatic review graph");var history=(DataGridView)type.GetField("historyResults",F).GetValue(v);if(history.Rows.Count!=0)throw new Exception("Unsaved data appeared in saved review list");if((int)type.GetField("m_GraphReadCount",F).GetValue(v)!=60)throw new Exception("Completed live graph was not retained");if(Directory.Exists(Path.Combine(root,"Data"))&&Directory.GetFiles(Path.Combine(root,"Data"),"*.csv",SearchOption.AllDirectories).Length>0)throw new Exception("Unexpected CSV");Console.WriteLine("PASS: result judged on live graph; no automatic review text or unsaved review row.");}}
}
